from pydantic import BaseModel, ConfigDict, model_validator, ValidationError


class Measurement(BaseModel):
    value: float
    unit: str

    model_config = ConfigDict(extra="forbid")

    @model_validator(mode="before")
    @classmethod
    def _normalize_input(cls, data: Dict[str, Any]) -> Dict[str, Any]:
        """
        If a ``raw`` key is present, split it into ``value`` and ``unit``.
        This runs before any field validation.
        """
        if "raw" in data:
            raw = data["raw"]
            if not isinstance(raw, str):
                raise TypeError("`raw` must be a string")
            # Regex: optional sign, digits with optional decimal, or .digits, followed by unit letters
            match = re.fullmatch(r"\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*([a-zA-Z%]+)\s*", raw)
            if not match:
                raise ValueError(f"Unable to parse raw measurement: {raw!r}")
            value_str, unit = match.groups()
            # Convert numeric part to float
            try:
                value = float(value_str)
            except ValueError as exc:
                raise ValueError(f"Invalid numeric value in raw measurement: {value_str!r}") from exc
            # Return a new dict without ``raw`` but with ``value`` and ``unit``
            new_data = {k: v for k, v in data.items() if k != "raw"}
            new_data.update({"value": value, "unit": unit})
            return new_data
        return data


def parse_measurement(data: dict) -> Measurement:
    """
    Parse a dictionary into a :class:`Measurement` instance,
    applying the pre‑validation normalisation.
    """
    return Measurement.model_validate(data)

